:root {
 --color-bg: #0b1020;
 --color-surface: #151d32;
 --color-primary: #8b7cff;
 --color-text: #f4f6ff;
 --color-muted: #b7c0d8;
 --radius-card: 18px;
}

body {
 background: var(--color-bg);
 color: var(--color-text);
}

.service-card {
 background: var(--color-surface);
 border-radius: var(--radius-card);
}

*,
*::before,
*::after {
 box-sizing: border-box;
}

.service-card {
 width: 100%;
 padding: 24px;
 border: 1px solid #34405d;
 margin-bottom: 20px;
}

html {
 font-size: 100%;
}

body {
 font-family: Arial, sans-serif;
 font-size: 1rem;
 line-height: 1.6;
}

h1 {
 font-size: clamp(2rem, 5vw, 3.5rem);
 line-height: 1.1;
}

p {
 color: var(--color-muted);
 max-width: 65ch;
}

.nav-inner {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 20px;
 flex-wrap: wrap;
}

.nav-links {
 display: flex;
 align-items: center;
 gap: 18px;
 flex-wrap: wrap;
}

.service-grid {
 display: grid;
 grid-template-columns: repeat(
 auto-fit,
 minmax(min(100%, 240px), 1fr)
 );
 gap: 22px;
}

.container {
 width: min(1120px, calc(100% - 32px));
 margin-inline: auto;
}

@media (max-width: 600px) {
 .nav-inner {
 align-items: flex-start;
 }

 .hero {
 padding-block: 48px;
 }

 .hero-actions {
 flex-direction: column;
 align-items: stretch;
 }
}

.service-card {
 transition: transform 180ms ease,
 border-color 180ms ease;
}

.service-card:hover {
 transform: translateY(-4px);
 border-color: var(--color-primary);
}

@media (prefers-reduced-motion: reduce) {
 *,
 *::before,
 *::after {
 scroll-behavior: auto !important;
 animation-duration: 0.01ms !important;
 animation-iteration-count: 1 !important;
 transition-duration: 0.01ms !important;
 }
}

html {
 color-scheme: dark;
}

img {
 display: block;
 max-width: 100%;
}

button,
a {
 -webkit-tap-highlight-color: transparent;
}

a:focus-visible,
button:focus-visible {
 outline: 3px solid #c4baff;
 outline-offset: 4px;
}

button {
 font: inherit;
 cursor: pointer;
}

:root {
 --bg: #0b1020;
 --surface: #151d32;
 --surface-soft: #1b2540;
 --primary: #8b7cff;
 --primary-light: #c4baff;
 --text: #f4f6ff;
 --muted: #b7c0d8;
 --border: #303b59;
 --radius: 18px;
 --container: 1120px;
}

*,
*::before,
*::after {
 box-sizing: border-box;
}

html {
 scroll-behavior: smooth;
 scroll-padding-top: 90px;
 color-scheme: dark;
}

body {
 margin: 0;
 background: var(--bg);
 color: var(--text);
 font-family: Arial, Helvetica, sans-serif;
 font-size: 16px;
 line-height: 1.6;
}

a {
 color: inherit;
 text-decoration: none;
}

button,
input,
textarea,
select {
 font: inherit;
}

button,
a {
 -webkit-tap-highlight-color: transparent;
}

a:focus-visible,
button:focus-visible {
 outline: 3px solid var(--primary-light);
 outline-offset: 4px;
}

.container {
 width: min(var(--container), calc(100% - 40px));
 margin-inline: auto;
}

.site-header {
 position: sticky;
 top: 0;
 z-index: 10;
 background: rgb(11 16 32 / 92%);
 border-bottom: 1px solid rgb(48 59 89 / 70%);
 backdrop-filter: blur(14px);
}

.nav-inner {
 min-height: 76px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 20px;
}

.brand {
 font-size: 1.35rem;
 font-weight: 800;
 letter-spacing: 0.08em;
}

.brand span {
 color: var(--primary);
}

.nav-links {
 display: flex;
 align-items: center;
 gap: 24px;
 flex-wrap: wrap;
}

.nav-links a:not(.nav-cta),
.site-footer a:last-child {
 color: var(--muted);
 transition: color 180ms ease;
}

.nav-links a:hover,
.site-footer a:last-child:hover {
 color: var(--text);
}

.nav-cta {
 padding: 10px 16px;
 border: 1px solid var(--border);
 border-radius: 999px;
}

.hero {
 padding-block: clamp(76px, 12vw, 142px);
}

.eyebrow {
 color: var(--primary-light);
 font-size: 0.76rem;
 font-weight: 700;
 letter-spacing: 0.16em;
}

.hero h1 {
 max-width: 850px;
 margin: 20px 0;
 font-size: clamp(2.5rem, 7vw, 5.4rem);
 line-height: 1.05;
 letter-spacing: -0.055em;
}

.hero h1 span {
 color: var(--primary-light);
}

.hero-copy {
 max-width: 620px;
 color: var(--muted);
 font-size: clamp(1rem, 2vw, 1.2rem);
}

.hero-actions {
 display: flex;
 gap: 14px;
 flex-wrap: wrap;
 margin-top: 30px;
}

.button {
 min-height: 48px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 padding: 12px 20px;
 border: 1px solid transparent;
 border-radius: 12px;
 font-weight: 700;
 transition: transform 180ms ease, background-color 180ms ease, border-color 180ms ease;
}

.button:hover {
 transform: translateY(-2px);
}

.button-primary {
 background: var(--primary);
 color: #0b1020;
}

.button-primary:hover {
 background: var(--primary-light);
}

.button-secondary {
 border-color: var(--border);
 background: var(--surface);
}

.button-secondary:hover {
 border-color: var(--primary);
}

.hero-note {
 display: flex;
 align-items: center;
 gap: 10px;
 margin-top: 34px;
 color: var(--muted);
 font-size: 0.9rem;
}

.status-dot {
 width: 9px;
 height: 9px;
 border-radius: 50%;
 background: #8b7cff;
 box-shadow: 0 0 14px rgb(139 124 255 / 65%);
}

.section {
 padding-block: 70px;
}

.section-heading {
 margin-bottom: 30px;
}

.section-heading h2,
.about-content h2,
.contact-section h2 {
 margin: 10px 0;
 font-size: clamp(2rem, 4vw, 3.2rem);
 line-height: 1.15;
 letter-spacing: -0.035em;
}

.section-heading > p:last-child,
.about-content > p:last-child,
.contact-section > p:not(.eyebrow) {
 max-width: 650px;
 color: var(--muted);
}

.service-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(min(100%, 250px), 1fr));
 gap: 20px;
}

.service-card {
 padding: 26px;
 border: 1px solid var(--border);
 border-radius: var(--radius);
 background: linear-gradient(145deg, var(--surface), #11182a);
 transition: transform 180ms ease, border-color 180ms ease;
}

.service-card:hover {
 transform: translateY(-4px);
 border-color: var(--primary);
}

.service-number {
 color: var(--primary-light);
 font-size: 0.85rem;
 font-weight: 700;
}

.service-card h3 {
 margin: 18px 0 8px;
 font-size: 1.35rem;
}

.service-card p {
 margin-bottom: 0;
 color: var(--muted);
}

.about-section {
 margin-top: 45px;
 padding-block: 76px;
 border-block: 1px solid var(--border);
 background: var(--surface);
}

.about-content {
 max-width: var(--container);
}

.contact-section {
 padding-block: 90px;
}

.contact-section .button {
 margin-top: 14px;
}

.site-footer {
 border-top: 1px solid var(--border);
}

.footer-inner {
 min-height: 90px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 18px;
 flex-wrap: wrap;
 padding-block: 18px;
}

.footer-inner p {
 color: var(--muted);
 font-size: 0.9rem;
}

@media (max-width: 600px) {
 .container {
 width: min(var(--container), calc(100% - 28px));
 }

 .nav-inner {
 padding-block: 14px;
 align-items: flex-start;
 }

 .nav-links {
 justify-content: flex-end;
 gap: 12px;
 font-size: 0.9rem;
 }

 .nav-cta {
 padding: 7px 11px;
 }

 .hero {
 padding-block: 72px;
 }

 .hero-actions {
 align-items: stretch;
 flex-direction: column;
 }

 .button {
 width: 100%;
 }

 .section {
 padding-block: 48px;
 }

 .service-card {
 padding: 22px;
 }

 .footer-inner {
 align-items: flex-start;
 flex-direction: column;
 }
}

@media (prefers-reduced-motion: reduce) {
 html {
 scroll-behavior: auto;
 }

 *,
 *::before,
 *::after {
 animation-duration: 0.01ms !important;
 animation-iteration-count: 1 !important;
 transition-duration: 0.01ms !important;
 }
}

@media print {
 .site-header,
 .hero-actions,
 .contact-section .button {
 display: none;
 }

 body {
 background: white;
 color: black;
 }

 .service-card,
 .about-section {
 background: white;
 color: black;
 border-color: #999;
 }
}
